class ScrollManager {
    private static instance: ScrollManager;
    
    public static getInstance(): ScrollManager {
      if (!ScrollManager.instance) {
        ScrollManager.instance = new ScrollManager();
      }
      return ScrollManager.instance;
    }
  
    public scrollToElement(elementId: string): void {
      setTimeout(() => {
        const element = document.getElementById(elementId);
        if (!element) {
          console.log(`[ScrollManager] Element ${elementId} not found`);
          return;
        }
  
        // Find the closest parent with 'scrollable' class
        const container = element.closest('.scrollable');
        if (!container) {
          console.log('[ScrollManager] No scrollable container found');
          return;
        }
  
        container.scrollTo({
          top: element.offsetTop - 20,
          behavior: 'smooth'
        });
      }, 100);
    }
  }
  
  export const scrollManager = ScrollManager.getInstance();