import React, { useEffect, useRef, useState } from 'react';
import { GameState } from '../../types/game';

declare global {
  interface Window {
    YT: {
      Player: any;
      PlayerState: any;
    };
    onYouTubeIframeAPIReady: () => void;
  }
}

interface AudioPlayerProps {
  gameState: GameState;
  isDM?: boolean;
}

export function AudioPlayer({ gameState, isDM = false }: AudioPlayerProps) {
  const playerRef = useRef<any>(null);
  const containerRef = useRef<HTMLDivElement>(null);
  const [isReady, setIsReady] = useState(false);

  // Load YouTube API
  useEffect(() => {
    if (!window.YT) {
      const tag = document.createElement('script');
      tag.src = 'https://www.youtube.com/iframe_api';
      const firstScriptTag = document.getElementsByTagName('script')[0];
      firstScriptTag.parentNode?.insertBefore(tag, firstScriptTag);

      window.onYouTubeIframeAPIReady = () => {
        setIsReady(true);
      };
    } else {
      setIsReady(true);
    }
  }, []);

  // Initialize player
  useEffect(() => {
    if (!isReady || !containerRef.current) return;

    playerRef.current = new window.YT.Player(containerRef.current, {
      height: '0',
      width: '0',
      playerVars: {
        autoplay: 0,
        controls: 0,
        disablekb: 1,
        fs: 0,
        modestbranding: 1,
        playsinline: 1,
        quality: 'small', // Force lowest quality for bandwidth
      },
      events: {
        onReady: () => {
          console.log('YouTube player ready');
        },
        onStateChange: (event: any) => {
          // Handle state changes
          if (event.data === window.YT.PlayerState.ENDED) {
            // Loop the track
            playerRef.current?.playVideo();
          }
        },
        onError: (event: any) => {
          console.error('YouTube player error:', event);
        }
      }
    });

    // Cleanup
    return () => {
      playerRef.current?.destroy();
    };
  }, [isReady]);

  // Handle track changes
  useEffect(() => {
    const currentTrack = gameState.audio.playlist.find(
      track => track.id === gameState.audio.currentTrackId
    );

    if (!playerRef.current || !currentTrack) return;

    if (currentTrack.id === 'silence') {
      playerRef.current.stopVideo();
    } else {
      playerRef.current.loadVideoById({
        videoId: currentTrack.youtubeId,
        startSeconds: 0,
        suggestedQuality: 'small'
      });
    }
  }, [gameState.audio.currentTrackId]);

  // Handle volume changes
  useEffect(() => {
    if (!playerRef.current) return;
    playerRef.current.setVolume(gameState.audio.volume);
  }, [gameState.audio.volume]);

  return (
    <div 
      ref={containerRef} 
      style={{ width: 0, height: 0, overflow: 'hidden' }}
      className="absolute"
    />
  );
}